  h -= ser * ss(0.95, 1.12, x) * (1.0 - ss(1.4, 1.55, x)) * ss(nip - 1.15, nip - 0.85, y) * (1.0 - ss(nip - 0.25, nip, y)) * ss(-0.1, 0.4, c.z) * 0.45 * full;
